200	        break;
201	      case BOOLEAN:
202	        generateBOOLEAN(obj, row);
203	        break;
204	      case TEXT:
205	      case BLOB:
206	      case STRING:
207	        generateTEXT(obj, row);
208	        break;
209	      default:
210	        LOGGER.error("Wrong data type {}.", schema.getType());
211	    }
212	  }
