50	  public void registerTableSchema(String tableName, List<String> idColumnNames) {
51	    CompactionTableSchema tableSchema = new CompactionTableSchema(tableName);
52	    List<IMeasurementSchema> measurementSchemas = new ArrayList<>();
53	    List<ColumnCategory> columnTypes = new ArrayList<>();
54	    for (String idColumnName : idColumnNames) {
55	      measurementSchemas.add(
56	          new MeasurementSchema(
57	              idColumnName, TSDataType.TEXT, TSEncoding.PLAIN, CompressionType.UNCOMPRESSED));
58	      columnTypes.add(ColumnCategory.TAG);
59	    }
60	    tableSchema.merge(new TableSchema(tableName, measurementSchemas, columnTypes));
61	    schema.registerTableSchema(tableSchema);
62	  }
