64	  public IDeviceID startChunkGroup(String tableName, List<String> idColumnFields)
65	      throws IOException {
66	    int idx = 0;
67	    String[] segments = new String[idColumnFields.size() + 1];
68	    segments[idx++] = tableName;
69	    for (String idField : idColumnFields) {
70	      segments[idx++] = idField;
71	    }
72	    currentDeviceId = new StringArrayDeviceID(segments);
73	    fileWriter.startChunkGroup(currentDeviceId);
74	    currentDeviceStartTime = Long.MAX_VALUE;
75	    currentDeviceEndTime = Long.MIN_VALUE;
76	    return currentDeviceId;
77	  }
