281	          sealedFiles.add(fileWriter.getIOWriter().getFile());
282	        }
283	
284	        for (final File sealedFile : sealedFiles) {
285	          final boolean deleteSuccess = FileUtils.deleteQuietly(sealedFile);
286	          LOGGER.warn(
287	              "Batch id = {}: {} delete the tsfile {} after failed to write tablets into {}. {}",
288	              currentBatchId.get(),
289	              deleteSuccess ? "Successfully" : "Failed to",
290	              sealedFile.getPath(),
291	              fileWriter.getIOWriter().getFile().getPath(),
292	              deleteSuccess ? "" : "Maybe the tsfile needs to be deleted manually.");
293	        }
294	        sealedFiles.clear();
295	
296	        fileWriter = null;
297	
298	        throw e;
299	      }
300	
301	      fileWriter.close();
302	      final File sealedFile = fileWriter.getIOWriter().getFile();
