42	    extends AstVisitor<Optional<TSStatus>, String> {
43	
44	  private static final Logger LOGGER =
45	      LoggerFactory.getLogger(LoadTableStatementDataTypeConvertExecutionVisitor.class);
46	
47	  @FunctionalInterface
48	  public interface StatementExecutor {
49	    // databaseName can NOT be null
50	    TSStatus execute(final Statement statement, final String databaseName);
51	  }
52	
53	  private final StatementExecutor statementExecutor;
54	
55	  public LoadTableStatementDataTypeConvertExecutionVisitor(StatementExecutor statementExecutor) {
56	    this.statementExecutor = statementExecutor;
57	  }
