59	  @Override
60	  public Optional<TSStatus> visitLoadTsFile(
61	      final LoadTsFile loadTsFileStatement, final String databaseName) {
62	    if (Objects.isNull(databaseName)) {
63	      LOGGER.warn(
64	          "Database name is unexpectedly null for LoadTsFileStatement: {}. Skip data type conversion.",
65	          loadTsFileStatement);
66	      return Optional.empty();
67	    }
68	
69	    LOGGER.info("Start data type conversion for LoadTsFileStatement: {}.", loadTsFileStatement);
70	
71	    for (final File file : loadTsFileStatement.getTsFiles()) {
72	      try (final TsFileInsertionEventTableParser parser =
73	          new TsFileInsertionEventTableParser(
74	              file,
75	              new TablePattern(true, null, null),
76	              Long.MIN_VALUE,
77	              Long.MAX_VALUE,
78	              null,
79	              null)) {
80	        for (final TabletInsertionEvent tabletInsertionEvent : parser.toTabletInsertionEvents()) {
81	          if (!(tabletInsertionEvent instanceof PipeRawTabletInsertionEvent)) {
82	            continue;
83	          }
84	          final PipeRawTabletInsertionEvent rawTabletInsertionEvent =
85	              (PipeRawTabletInsertionEvent) tabletInsertionEvent;
86	
87	          final LoadConvertedInsertTabletStatement statement =
88	              new LoadConvertedInsertTabletStatement(
89	                  PipeTransferTabletRawReq.toTPipeTransferRawReq(
90	                          rawTabletInsertionEvent.convertToTablet(),
91	                          rawTabletInsertionEvent.isAligned())
92	                      .constructStatement());
93	
94	          TSStatus result;
95	          try {
96	            result =
97	                statement.accept(
98	                    LoadTsFileDataTypeConverter.STATEMENT_STATUS_VISITOR,
99	                    statementExecutor.execute(statement, databaseName));
100	
101	            // Retry max 5 times if the write process is rejected
102	            for (int i = 0;
103	                i < 5
104	                    && result.getCode()
105	                        == TSStatusCode.LOAD_TEMPORARY_UNAVAILABLE_EXCEPTION.getStatusCode();
106	                i++) {
107	              Thread.sleep(100L * (i + 1));
108	              result =
109	                  statement.accept(
110	                      LoadTsFileDataTypeConverter.STATEMENT_STATUS_VISITOR,
111	                      statementExecutor.execute(statement, databaseName));
112	            }
113	          } catch (final Exception e) {
114	            if (e instanceof InterruptedException) {
115	              Thread.currentThread().interrupt();
116	            }
117	            result = statement.accept(LoadTsFileDataTypeConverter.STATEMENT_EXCEPTION_VISITOR, e);
118	          }
