  private final Map<String, Long> table2RowNumber;
  private Random random;

  public TsFileTableGenerator(final File tsFile) throws IOException {
    this.tsFile = tsFile;
    this.writer = new TsFileWriter(tsFile);
    this.table2MeasurementSchema = new HashMap<>();
    this.table2ColumnCategory = new HashMap<>();
    this.table2LastTime = new HashMap<>();
    this.table2RowNumber = new HashMap<>();
    this.random = new Random();
  }

  public void resetRandom() {
    random = new Random();
  }

  public void resetRandom(final long seed) {
    random = new Random(seed);
  }

  public void registerTable(
      final String tableName,
      final List<IMeasurementSchema> measurementSchemaList,
