    if (table2MeasurementSchema.containsKey(tableName)) {
      LOGGER.error("Register same table {}.", tableName);
      return;
    }
    writer.registerTableSchema(
        new TableSchema(tableName, measurementSchemaList, columnCategoryList));
    table2MeasurementSchema.put(tableName, measurementSchemaList);
    table2ColumnCategory.put(tableName, columnCategoryList);
    table2LastTime.put(tableName, 0L);
    table2RowNumber.put(tableName, 0L);
  }

