    final List<IMeasurementSchema> schemas = table2MeasurementSchema.get(tableName);
    final List<ColumnCategory> columnCategories = table2ColumnCategory.get(tableName);

    final List<String> columnNames = new ArrayList<>(schemas.size());
    final List<TSDataType> dataTypes = new ArrayList<>(schemas.size());
    for (final IMeasurementSchema schema : schemas) {
      columnNames.add(schema.getMeasurementName());
      dataTypes.add(schema.getType());
    }

    final Tablet tablet = new Tablet(tableName, columnNames, dataTypes, columnCategories);
    final Object[] values = tablet.values;
    final int columnNum = schemas.size();
    long startTime = table2LastTime.get(tableName);

    writer.setTableWriteAligned(isAligned);
    for (int r = 0; r < number; r++) {
